/* Only the calls <pdf.h> declares leave the library. */
{
	global:
		pdf_writer_create;
		pdf_writer_destroy;
		pdf_writer_begin_page;
		pdf_writer_end_page;
		pdf_writer_set_fill_color;
		pdf_writer_move_to;
		pdf_writer_line_to;
		pdf_writer_curve_to;
		pdf_writer_close_path;
		pdf_writer_fill;
		pdf_writer_attach_file;
		pdf_writer_save;
	local:
		*;
};
